try {
  const r = await fetch("https://www.plantuml.com/plantuml/api/png", {
    method: "POST",
    headers: { "Content-Type": "text/plain" },
    body: "@startuml\nBob -> Alice : hello\n@enduml",
  });
  const buf = new Uint8Array(await r.arrayBuffer());
  const b64 = btoa(String.fromCharCode(...buf));
  return { status: r.status, contentType: r.headers.get("content-type"), bytes: buf.length, head: b64.slice(0, 24) };
} catch (e) {
  return { error: String(e) };
}

